{
	"name": "@tinfoilsh/opencode-provider",
	"version": "0.1.3",
	"description": "Verifiably-private models from Tinfoil secure enclaves, for the opencode coding agent",
	"type": "module",
	"license": "Apache-2.0",
	"main": "./tinfoil.ts",
	"exports": {
		".": "./tinfoil.ts",
		"./server": "./server.ts",
		"./tui": "./tui.ts"
	},
	"repository": {
		"type": "git",
		"url": "git+https://github.com/tinfoilsh/opencode-provider.git"
	},
	"homepage": "https://tinfoil.sh/coding-agents",
	"bugs": {
		"url": "https://github.com/tinfoilsh/opencode-provider/issues"
	},
	"keywords": [
		"opencode",
		"opencode-plugin",
		"tinfoil",
		"provider",
		"privacy",
		"confidential-computing",
		"attestation"
	],
	"peerDependencies": {
		"@opencode-ai/plugin": "*",
		"@opencode/plugin": "^2.0.30",
		"@opentui/core": ">=0.5.0",
		"@opentui/solid": ">=0.5.0",
		"solid-js": "^1.9.0"
	},
	"files": [
		"server.ts",
		"tinfoil.ts",
		"tui.ts",
		"README.md",
		"LICENSE"
	],
	"scripts": {
		"check": "tsc --noEmit",
		"prepublishOnly": "npm run check"
	},
	"publishConfig": {
		"access": "public"
	},
	"dependencies": {
		"@ai-sdk/openai-compatible": "^2.0.41",
		"tinfoil": "^1.2.1"
	},
	"devDependencies": {
		"@opencode-ai/plugin": "^1.18.27",
		"@opencode/plugin": "^2.0.30",
		"@opentui/core": "^0.5.17",
		"@opentui/solid": "^0.5.17",
		"@types/node": "^24.0.0",
		"solid-js": "^1.9.0",
		"typescript": "^5.9.0"
	},
	"peerDependenciesMeta": {
		"@opencode/plugin": {
			"optional": true
		},
		"@opentui/core": {
			"optional": true
		},
		"@opentui/solid": {
			"optional": true
		},
		"solid-js": {
			"optional": true
		},
		"@opencode-ai/plugin": {
			"optional": true
		}
	},
	"engines": {
		"opencode": ">=1.19.1 <2 || >=2.0.30"
	}
}
